import java.util.*;

class Solution {
  Map<Long, Integer> memo;
  char[] a;
  int k, n;

  public int maxPartitionsAfterOperations(String s, int k) {
    this.a = s.toCharArray();
    this.k = k;
    n = a.length;
    memo = new HashMap<>();
    return dfs(0, 0, 0) + 0;
  }

  int dfs(int i, int mask, int used) {
    if (i == n) return mask == 0 ? 0 : 1;
    long key = (((long) i << 27) | ((long) used << 26) | (mask & 0x3ffffffL));
    Integer z = memo.get(key);
    if (z != null) return z;
    int ans = take(i, mask, used, a[i] - 'a', false);
    if (used == 0) for (int c = 0; c < 26; c++) ans = Math.max(ans, take(i, mask, 1, c, true));
    memo.put(key, ans);
    return ans;
  }

  int take(int i, int mask, int used, int c, boolean changed) {
    int bit = 1 << c;
    if ((mask & bit) != 0) return dfs(i + 1, mask, used);
    if (Integer.bitCount(mask) < k) return dfs(i + 1, mask | bit, used);
    return 1 + dfs(i + 1, bit, used);
  }
}
